/**
 * Falcon rule universes (design 4.3). Membership is today's: every result on
 * them carries the survivorship flag (check 15), and the lists of stocks
 * carry the hindsight check (14).
 *
 * falcon_semis mirrors SECTORS.semis in packages/engine/src/universe.ts (the
 * engine's watched list, 58 tickers). It is copied, not imported, so the
 * backtester does not depend on the engine package; a test keeps them equal.
 *
 * The wide lists (falcon_universe, falcon_graph, us_large_caps, sp500_today)
 * come from src/universe-lists.ts, generated by scripts/build-universes.ts:
 * tickers and an as-of date only.
 *
 * Pure; safe in the browser.
 */

import { UNIVERSE_LISTS } from "./universe-lists";

export const UNIVERSE_BASES = ["falcon_semis", "sector_etfs", "falcon_universe", "falcon_graph", "us_large_caps", "sp500_today"] as const;
export type UniverseBase = (typeof UNIVERSE_BASES)[number];

export type UniverseInfo = {
  /** In a sentence: "Universe: <label> (N tickers, today's membership)". */
  label: string;
  /** Plain words for buttons and version lists: "S&P 500 today". */
  short: string;
  tickers: string[];
  note: string;
  /** Membership date of the list (null for fixed lists such as the sector ETFs). */
  asOf: string | null;
  /**
   * A list of stocks picked by how companies stand today (size, trading,
   * index membership, Falcon's own coverage). A test over past years on it is
   * a confirmed hindsight list (check 14), whatever the rules do.
   */
  todaysPick: boolean;
};

const split = (s: string) => s.split(" ").filter(Boolean);
const wide = (k: keyof typeof UNIVERSE_LISTS) => ({ tickers: split(UNIVERSE_LISTS[k].tickers), asOf: UNIVERSE_LISTS[k].asOf });

const fu = wide("falcon_universe");
const fg = wide("falcon_graph");
const lc = wide("us_large_caps");
const sp = wide("sp500_today");

