/** "the S&P 500 members today (as of 2026-11-12)": the label with the list's date, for rules text and checks. */
export function datedLabel(u: UniverseInfo): string {
  return u.asOf ? `${u.label} (as of ${u.asOf})` : u.label;
}

/** Universes with more tickers than the AI prompt lists one by one. */
export const LIST_TICKERS_IN_PROMPT_MAX = 60;
